window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[277]={"id":"277","numero":277,"titre":"Lithiase biliaire et complications","objectifs":[{"id":"277-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une lithiase biliaire et des différentes complications","contenu":"<p>La <strong><span class=\"kw-def\">lithiase biliaire</span></strong> désigne la présence de <span class=\"kw-def\">calculs</span> formés à partir de la bile. La <span class=\"kw-def\">lithiase vésiculaire</span> (calcul dans la <span class=\"kw-clinique\">vésicule</span>) est la forme la plus fréquente ; elle est <strong>asymptomatique dans <span class=\"kw-chiffre\">80 %</span></strong> des cas. <span class=\"kw-clinique\">Les</span> manifestations symptomatiques et compliquées découlent de la mobilisation d’un calcul et de son blocage à différents niveaux de l’arbre biliaire.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition / mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Lithiase vésiculaire</span></strong></td><td>Calcul formé à partir de la bile, localisé dans la <span class=\"kw-def\">vésicule biliaire</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Colique hépatique</span></strong></td><td>Douleur par mise en tension brutale des voies biliaires lors du blocage <span class=\"kw-clinique\">transitoire</span> d’un calcul (canal cystique ou VBP)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Cholécystite</span> aiguë</strong></td><td><span class=\"kw-alerte\">Infection aiguë</span> de la <span class=\"kw-clinique\">vésicule</span> par <strong>obstruction prolongée du canal cystique</strong></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Lithiase de la VBP</span></strong></td><td>Calcul dans la <span class=\"kw-def\">voie biliaire principale</span> ; peut causer un <span class=\"kw-clinique\">ictère</span> si obstruction prolongée</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Angiocholite</span></strong></td><td><span class=\"kw-alerte\">Infection bactérienne de la VBP</span> par enclavement d’un calcul au niveau de l’<span class=\"kw-def\">ampoule de Vater</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Pancréatite aiguë</span></strong></td><td><span class=\"kw-alerte\">Inflammation aiguë du pancréas</span> par migration d’un calcul dans l’ampoule de Vater</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Iléus</span> biliaire</strong></td><td>Syndrome <span class=\"kw-alerte\">occlusif</span> par obstruction duodénale/iléale par un calcul</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> Le tableau de synthèse comparant douleur, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">ictère</span>, biologie et écho de chaque forme se trouve dans l’onglet <em>Astuces &amp; Pièges</em> (discriminant clé).</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/biliary-tree-anatomy","label":"Radiopaedia : Biliary tree anatomy"},{"href":"https://radiopaedia.org/articles/gallstones-1","label":"Radiopaedia : Gallstones 1"},{"href":"https://radiopaedia.org/articles/acute-cholecystitis","label":"Radiopaedia : Acute cholecystitis"},{"href":"https://radiopaedia.org/articles/pancreatitis","label":"Radiopaedia : Pancreatitis"}]},{"id":"277-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence de la pathologie lithiasique biliaire, la fréquence de survenue de symptômes et les indications de dépistage.","contenu":"<p>La <span class=\"kw-def\">lithiase vésiculaire</span> touche <span class=\"kw-chiffre\">20 %</span> de la population générale, et jusqu’à <span class=\"kw-chiffre\">60 %</span> à <span class=\"kw-chiffre\">80 ans</span> (<span class=\"kw-bio\">prévalence croissante avec l’âge</span>).</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Asymptomatique</span> dans <span class=\"kw-chiffre\">80 %</span> des cas</li>\n        <li><span class=\"kw-clinique\">Symptomatique</span> dans <span class=\"kw-chiffre\">20 %</span> des cas</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Dépistage</span>.</strong> Le dépistage de la <span class=\"kw-def\">lithiase vésiculaire</span> <span class=\"kw-alerte\">n’est PAS indiqué</span> chez le sujet asymptomatique.</div>","frequence":0},{"id":"277-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence des complications de la lithiase biliaire","contenu":"<p>Parmi <span class=\"kw-clinique\">les</span> sujets <span class=\"kw-clinique\">symptomatiques</span>, la probabilité cumulée de complication est faible : <span class=\"kw-chiffre\">5 %</span> des sujets symptomatiques développent une complication (<span class=\"kw-etio\">cholécystite</span>, <span class=\"kw-etio\">migration</span>, <span class=\"kw-etio\">angiocholite</span>, <span class=\"kw-etio\">pancréatite</span>).</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La grande majorité des <span class=\"kw-def\">lithiases vésiculaires</span> reste <span class=\"kw-clinique\">silencieuse</span> ; le risque évolutif ne concerne qu’une minorité de patients devenus symptomatiques.</div>","frequence":0},{"id":"277-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques des calculs et les facteurs de risque de calculs cholestéroliques et pigmentaires","contenu":"<p>Deux grands types de calculs, de fréquence et de mécanisme distincts :</p>\n      <table >\n        <thead><tr><th></th><th>Calculs cholestéroliques</th><th>Lithiase p<span class=\"kw-chiffre\">igm</span>entaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-chiffre\">80 %</span></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Augmentation de la concentration biliaire en <span class=\"kw-def\">cholestérol</span> ; sursaturation → nucléation → précipitation</td>\n            <td><span class=\"kw-def\">Déconjugaison de la bilirubine</span> qui devient insoluble (la <span class=\"kw-bio\">bilirubine</span> conjuguée est soluble, la non-conjuguée est insoluble)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Facteurs de risque</span></strong></td>\n            <td>\n              <strong>Âge :</strong> <span class=\"kw-chiffre\">&gt; 50-65 ans</span> ; <span class=\"kw-etio\">ATCD familiaux</span><br>\n              <strong>Femme :</strong> <span class=\"kw-etio\">sexe féminin</span> ; <span class=\"kw-etio\">multiparité</span> ; <span class=\"kw-etio\">grossesse</span><br>\n              <strong>Pondéral :</strong> <span class=\"kw-etio\">surpoids/obésité</span> ; <span class=\"kw-etio\">variations importantes de poids</span><br>\n              <strong>Digestif :</strong> <span class=\"kw-etio\">jeûne prolongé</span> ; <span class=\"kw-etio\">nutrition parentérale</span> ; ATCD de <span class=\"kw-etio\">gastrectomie ou bypass</span><br>\n              <strong>Médicaments :</strong> <span class=\"kw-ttt\">œstrogènes</span> ; <span class=\"kw-ttt\">fibrates</span> ; <span class=\"kw-ttt\">analogues de la somatostatine</span>\n            </td>\n            <td>\n              <strong>Hémolyse :</strong> <span class=\"kw-etio\">drépanocytose</span> ; <span class=\"kw-etio\">thalassémie</span> (augmentation de la production de <span class=\"kw-bio\">bilirubine</span>)<br>\n              <strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-etio\">infections biliaires chroniques</span><br>\n              <strong>Obstacle :</strong> <span class=\"kw-etio\">sténose bénigne/maligne de la VBP</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"277-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les trois complications de la pathologie lithiasique vésiculaire et leur mécanisme","contenu":"<p>Trois complications principales selon le niveau et la durée du blocage :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Colique hépatique</span></td><td>Blocage <span class=\"kw-clinique\">transitoire</span> d’un calcul (canal cystique ou VBP) → <span class=\"kw-clinique\">mise en tension brutale des voies biliaires</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cholécystite aiguë</span></td><td><span class=\"kw-alerte\">Obstruction prolongée du canal cystique</span> → inflammation puis <span class=\"kw-alerte\">infection</span> de la <span class=\"kw-clinique\">vésicule</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Migration lithiasique</span> (vers la VBP)</td><td>Passage d’un calcul dans la VBP → peut se compliquer de <span class=\"kw-etio\">lithiase de la VBP</span>, <span class=\"kw-etio\">angiocholite</span> ou <span class=\"kw-etio\">pancréatite aiguë</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"277-8","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la lithiase cholestérolique et de la lithiase pigmentaire","contenu":"<table >\n        <thead><tr><th>Type</th><th><span class=\"kw-def\">Physiopathologie</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Lithiase cholestérolique</span></td><td>Augmentation de la concentration biliaire en <span class=\"kw-def\">cholestérol</span> (causée par <span class=\"kw-clinique\">les</span> FR) → <span class=\"kw-def\">sursaturation</span> → <span class=\"kw-def\">nucléation</span> → <span class=\"kw-def\">précipitation lithiasique</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Lithiase pigmentaire</span></td><td><span class=\"kw-def\">Déconjugaison de la bilirubine</span> qui devient insoluble : la <span class=\"kw-bio\">bilirubine conjuguée est soluble, la non-conjuguée est insoluble</span> → précipitation</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"277-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de la douleur biliaire","contenu":"<p>La <strong><span class=\"kw-clinique\">colique hépatique</span></strong> est la traduction douloureuse du blocage transitoire d’un calcul. Ses caractéristiques sémiologiques :</p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type</strong></td><td><span class=\"kw-clinique\">brutale, intense</span></td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Continue, à type de <span class=\"kw-clinique\">broiement</span> ou <span class=\"kw-clinique\">crampe</span></td></tr>\n          <tr><td><strong>Localisation</strong></td><td><span class=\"kw-clinique\">épigastrique</span> ou <span class=\"kw-clinique\">hypochondre droit</span></td></tr>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-chiffre\">&lt; 6 h</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Irradiation</span></strong></td><td>Hémi-ceinture → <span class=\"kw-clinique\">épaule / omoplate</span></td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">inhibition de la respiration</span> ; <span class=\"kw-clinique\">nausées</span>, vomissements</td></tr>\n          <tr><td><strong>Signe spécifique</strong></td><td><span class=\"kw-clinique\">signe de Murphy</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Signe négatif capital.</strong> Une <span class=\"kw-clinique\">colique hépatique</span> simple ne comporte <span class=\"kw-alerte\">JAMAIS de fièvre ni d’ictère</span> — leur présence signe une complication (<span class=\"kw-clinique\">cholécystite</span>, angiocholite).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — Douleur abdominale aiguë</em></p>","frequence":0},{"id":"277-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois principaux diagnostics différentiels à évoquer devant une colique hépatique","contenu":"<p>Devant une <span class=\"kw-clinique\">douleur épigastrique / de l’hypochondre droit</span>, trois diagnostics différentiels principaux à éliminer :</p>\n      <ul>\n        <li><span class=\"kw-etio\">SCA</span> (<span class=\"kw-etio\">syndrome coronarien aigu</span>) — surtout en cas de <span class=\"kw-clinique\">douleur épigastrique trompeuse</span></li>\n        <li><span class=\"kw-def\">UGD</span> (<span class=\"kw-etio\">ulcère gastro-duodénal</span>)</li>\n        <li><span class=\"kw-etio\">Pancréatite aiguë</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span></em></p>","frequence":0},{"id":"277-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic positif de la lithiase vésiculaire symptomatique simple","contenu":"<p>Le diagnostic de <span class=\"kw-clinique\">lithiase vésiculaire</span> symptomatique simple repose sur un faisceau clinico-<span class=\"kw-ttt\">biologique</span>-échographique :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Colique hépatique</span> <span class=\"kw-chiffre\">&lt; 6 h</span> ; <span class=\"kw-alerte\">pas de fièvre</span> ; <span class=\"kw-alerte\">pas d’ictère</span> ; signe de <span class=\"kw-clinique\">Murphy</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td>Aucune anomalie : <span class=\"kw-bio\">bilan hépatique normal</span> ; <span class=\"kw-bio\">pas de syndrome inflammatoire</span> (sauf si migration lithiasique associée)</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td><td>Calculs vésiculaires : <span class=\"kw-imagerie\">hyperéchogènes</span> ; <span class=\"kw-imagerie\">cône d’ombre postérieur</span> ; <span class=\"kw-imagerie\">mobiles</span> avec le patient (<span class=\"kw-chiffre\">Se 95 %</span>, meilleure que <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span>). Ne pas confondre avec le <span class=\"kw-imagerie\">sludge</span> (bile épaisse)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span class=\"kw-imagerie\">sludge</span> (boue biliaire) est hyperéchogène mais SANS cône d’ombre et déclive — à ne pas prendre pour un calcul.</div>","frequence":3},{"id":"277-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","contenu":"<p>Deux volets : soulager la crise, puis prévenir la récidive.</p>\n      <ul>\n        <li><strong>Traitement de la crise</strong> (en <span class=\"kw-alerte\">urgence</span>, voie <strong>parentérale</strong>) :\n          <span class=\"kw-ttt\">antispasmodiques</span> (<span class=\"kw-ttt\">phloroglucinol</span> ou <span class=\"kw-ttt\">trimébutine</span>) ; <span class=\"kw-ttt\">antalgiques</span> ± <span class=\"kw-ttt\">AINS</span> <span class=\"kw-ci\">en l’absence de contre-indication</span></li>\n        <li><strong><span class=\"kw-ttt\">Cholécystectomie</span></strong> (sous cœlioscopie de préférence) pour éviter récidive/complication, réalisée rapidement une fois la crise calmée (<span class=\"kw-chiffre\">&lt; 1 mois</span>)</li>\n      </ul>","frequence":1},{"id":"277-13","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","contenu":"<p>L’examen de <strong><span class=\"kw-chiffre\">1ʳᵉ intention</span></strong> devant une lithiase biliaire symptomatique est l’<strong><span class=\"kw-imagerie\">échographie abdominale</span></strong> (<span class=\"kw-chiffre\">Se 95 %</span> pour <span class=\"kw-clinique\">les</span> calculs vésiculaires, <span class=\"kw-alerte\">meilleure que TDM/IRM</span>).</p>\n      <p>Le <span class=\"kw-imagerie\">scanner abdominal</span> ou la <span class=\"kw-imagerie\">bili-IRM</span> sont discutés en <span class=\"kw-chiffre\">2ᵉ intention</span> (calcul vésiculaire isolé : pas d’indication).</p>","frequence":2},{"id":"277-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","contenu":"<p><strong>Mécanisme :</strong> migration de petits calculs <span class=\"kw-def\">dans la voie biliaire principale</span>, le plus souvent <span class=\"kw-clinique\">transitoire</span> (le calcul passe puis est évacué).</p>\n      <p><strong>Diagnostic :</strong></p>\n      <ul>\n        <li>Élévation <span class=\"kw-clinique\">transitoire</span> des <span class=\"kw-bio\">transaminases</span>, <span class=\"kw-bio\">diminuant de &gt; 50 % en <span class=\"kw-chiffre\">&lt; 48 h</span></span> (<span class=\"kw-bio\">bilirubine</span> et <span class=\"kw-bio\">γ-GT</span> normales)</li>\n        <li><span class=\"kw-imagerie\">Échographie</span> : <span class=\"kw-imagerie\">parois vésiculaires fines</span>, <span class=\"kw-imagerie\">dilatation modérée ± inconstante de la VBP</span>, calcul rarement vu dans la VBP (écho souvent identique à une <span class=\"kw-clinique\">colique hépatique</span> simple)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> La <span class=\"kw-bio\">cinétique des transaminases</span> (pic précoce qui s’effondre en <span class=\"kw-chiffre\">&lt; 48 h</span>) est le meilleur signe de migration.</div>","frequence":0},{"id":"277-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","contenu":"<p>L’<strong><span class=\"kw-imagerie\">échographie</span></strong> est l’examen de <span class=\"kw-chiffre\">1ʳᵉ intention</span>, mais a une <span class=\"kw-alerte\">mauvaise sensibilité</span> : elle met rarement en évidence la <span class=\"kw-radio\">dilatation de la VBP</span> ou le calcul cholédocien, et ne montre souvent que <span class=\"kw-clinique\">les</span> calculs vésiculaires.</p>\n      <p>Le diagnostic repose donc <strong>essentiellement sur l’élévation transitoire des <span class=\"kw-bio\">transaminases</span></strong>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> La <span class=\"kw-imagerie\">bili-IRM</span> et l’<span class=\"kw-imagerie\">écho-endoscopie</span> sont <span class=\"kw-clinique\">les</span> meilleurs examens pour voir un calcul cholédocien, mais ils ne sont <span class=\"kw-alerte\">PAS utilisés en première intention</span>. Le <span class=\"kw-imagerie\">TDM</span> a une valeur diagnostique inférieure pour les calculs de la VBP.</div>","frequence":0},{"id":"277-16","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","contenu":"<p><strong>Mécanisme :</strong> obstruction prolongée du canal cystique → inflammation de la paroi vésiculaire puis <span class=\"kw-alerte\">infection aiguë</span> de la <span class=\"kw-clinique\">vésicule</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Colique hépatique</span> persistante (<span class=\"kw-chiffre\">&gt; 6 h</span>, souvent <span class=\"kw-chiffre\">&gt; 24 h</span>) ; <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> fréquent (<span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span>) ; <span class=\"kw-alerte\">pas d’ictère</span> (sauf Mirizzi) ; signes d’irritation péritonéale possibles (<span class=\"kw-clinique\">cholécystite</span> grave)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">Syndrome inflammatoire</span> (hyperPNN, <span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">PCT</span>) ; <span class=\"kw-bio\">bilan hépatique normal</span> ; <span class=\"kw-bio\">lipase normale</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td><td>Paroi vésiculaire <span class=\"kw-chiffre\">&gt; 4 mm</span> en <span class=\"kw-imagerie\">triple feuillet</span> ; distension vésiculaire (&gt; <span class=\"kw-chiffre\">4 cm</span>) ; calcul vésiculaire (hyperéchogène, mobile, cône d’ombre) ; <span class=\"kw-clinique\">Murphy échographique</span></td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td><span class=\"kw-bio\">Hémocultures</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"277-17","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","contenu":"<p>L’examen de <strong><span class=\"kw-chiffre\">1ʳᵉ intention</span></strong> devant une <span class=\"kw-clinique\">cholécystite</span> aiguë est l’<strong><span class=\"kw-imagerie\">échographie abdominale</span></strong> (paroi <span class=\"kw-chiffre\">&gt; 4 mm</span> en <span class=\"kw-imagerie\">triple feuillet</span>, distension <span class=\"kw-chiffre\">&gt; 4 cm</span>, <span class=\"kw-clinique\">Murphy échographique</span>).</p>\n      <p>Le <span class=\"kw-imagerie\">scanner abdominal</span> peut être discuté en <span class=\"kw-chiffre\">2ᵉ intention</span> (doute diagnostique, complications, <span class=\"kw-ci\">contre-indication</span> chirurgicale).</p>","frequence":0},{"id":"277-18","rang":"B","rubrique":"Contenu multimédia","titre":"Bili-IRM d’un empierrement cholédocien","contenu":"<p>La <strong><span class=\"kw-imagerie\">bili-IRM</span></strong> (cholangio-<span class=\"kw-imagerie\">IRM</span>) est, avec l’<span class=\"kw-imagerie\">écho-endoscopie</span>, le meilleur examen pour mettre en évidence des calculs de la voie biliaire principale (<span class=\"kw-chiffre\">Se &gt; 90 %</span>). Un <strong>empierrement cholédocien</strong> correspond à de <span class=\"kw-alerte\">multiples calculs occupant la VBP</span>.</p>\n      <table >\n        <thead><tr><th>Élément sémiologique</th><th>Aspect <span class=\"kw-imagerie\">bili-IRM</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie biliaire principale</strong></td><td><span class=\"kw-imagerie\">Hypersignal T2</span> intense (la bile statique en T2 brille)</td></tr>\n          <tr><td><strong>Calculs cholédociens</strong></td><td><span class=\"kw-imagerie\">Images hypointenses en T2</span> (« defects ») au sein du conduit hypersignal — <span class=\"kw-alerte\">absence de rehaussement</span> après injection</td></tr>\n          <tr><td><strong>Anatomie analysable</strong></td><td>Conduit hépatique droit, gauche, cystique, cholédoque — utile pour le bilan pré-<span class=\"kw-imagerie\">CPRE</span></td></tr>\n          <tr><td><strong>Empierrement</strong></td><td><span class=\"kw-alerte\">Multiples defects</span> alignés dans la VBP, avec dilatation d’amont</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mémo signal.</strong> En T2 : la <span class=\"kw-imagerie\">bile = blanche</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">calculs = noirs</span>. Tout point noir dans un canal blanc et dilaté = calcul jusqu’à preuve du contraire.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/277/bili-irm-empierrement-choledocien.png\" alt=\"Bili-IRM (cholangio-IRM) chez deux patients : voie biliaire principale en hypersignal T2 contenant de multiples calculs hypointenses (defects) réalisant un empierrement cholédocien\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Bili-IRM (cholangio-IRM)</span> — <span class=\"kw-def\">empierrement cholédocien</span>. La <span class=\"kw-imagerie\">VBP en hypersignal T2</span> (bile blanche) contient de <span class=\"kw-alerte\">multiples calculs hypointenses</span> (« defects » noirs) ; conduits hépatiques droit/gauche, cystique et cholédoque analysables. Source : banque « Imagerie à connaître » (item 277, p.66).</figcaption>\n      </figure>","frequence":2},{"id":"277-19","rang":"B","rubrique":"Contenu multimédia","titre":"Aspect échographique d’une cholécystite aiguë","contenu":"<p><strong>Signes diagnostiques principaux</strong> (faisceau d’arguments) :</p>\n      <ul>\n        <li>Paroi vésiculaire <span class=\"kw-imagerie\">épaissie &gt; 4 mm</span>, aspect en <span class=\"kw-imagerie\">triple feuillet</span></li>\n        <li><span class=\"kw-imagerie\">Distension vésiculaire</span> (<span class=\"kw-chiffre\">&gt; 4 cm</span>)</li>\n        <li>Calcul vésiculaire <span class=\"kw-imagerie\">hyperéchogène</span>, mobile, avec <span class=\"kw-imagerie\">cône d’ombre postérieur</span></li>\n      </ul>\n      <p><strong>Autres signes</strong> (non indispensables au diagnostic, mais utiles) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Signe de Murphy échographique</span> — douleur au passage de la sonde sur la <span class=\"kw-clinique\">vésicule</span></li>\n        <li><span class=\"kw-imagerie\">Sludge intra-vésiculaire</span> — bile épaisse hyperéchogène déclive, <span class=\"kw-alerte\">sans cône d’ombre</span> (à distinguer du calcul)</li>\n        <li><span class=\"kw-imagerie\">Épanchement péri-vésiculaire</span> — <span class=\"kw-alerte\">signe de gravité</span></li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/277/echo-cholecystite-aigue.png\" alt=\"Échographie hépato-biliaire chez deux patients : paroi vésiculaire épaissie en triple feuillet, distension, calcul intra-vésiculaire hyperéchogène avec cône d'ombre postérieur, sludge et épanchement péri-vésiculaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Échographie hépato-biliaire</span> — <span class=\"kw-etio\">cholécystite aiguë lithiasique</span>. <span class=\"kw-imagerie\">Paroi vésiculaire épaissie &gt; 4 mm</span> en triple feuillet, <span class=\"kw-imagerie\">distension &gt; 4 cm</span>, <span class=\"kw-imagerie\">calcul hyperéchogène avec cône d'ombre postérieur</span> ; signes associés : sludge, épanchement péri-vésiculaire (gravité). Source : banque « Imagerie à connaître » (item 277, p.67).</figcaption>\n      </figure>","frequence":0},{"id":"277-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la cholécystite aiguë","contenu":"<ul>\n        <li><strong>Symptomatique :</strong> <span class=\"kw-ttt\">remplissage</span> ; <span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> ; <span class=\"kw-ttt\">antalgiques</span> ; <span class=\"kw-ttt\">AINS</span></li>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou <span class=\"kw-ttt\">C3G + imidazolé</span> pendant <span class=\"kw-chiffre\">7 jours</span></li>\n        <li><strong><span class=\"kw-ttt\">Cholécystectomie</span> en <span class=\"kw-alerte\">URGENCE</span></strong> par voie <span class=\"kw-ttt\">laparoscopique/cœlioscopie</span> (<span class=\"kw-chiffre\">&lt; 72 h</span>)</li>\n      </ul>","frequence":0},{"id":"277-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître le délai de prise en charge chirurgicale de la cholécystite","contenu":"<div class=\"callout callout-danger\"><strong>Délai clé.</strong> La <span class=\"kw-ttt\">cholécystectomie</span> de la <span class=\"kw-clinique\">cholécystite</span> aiguë est réalisée <span class=\"kw-alerte\">en urgence</span>, dans un délai <span class=\"kw-chiffre\">&lt; 72 h</span>, par voie <span class=\"kw-ttt\">cœlioscopique</span> (<span class=\"kw-ttt\">laparoscopique</span>).</div>\n      <p>Au-delà de <span class=\"kw-chiffre\">72 h</span>, l’inflammation locale rend la <span class=\"kw-etio\">dissection</span> plus risquée → certains centres choisissent alors une <span class=\"kw-ttt\">chirurgie</span> différée à <span class=\"kw-chiffre\">6-8 semaines</span> sous couvert d’<span class=\"kw-ttt\">antibiothérapie</span>.</p>","frequence":0},{"id":"277-22","rang":"A","rubrique":"Suivi et / ou pronostic","titre":"Connaître les complications septiques de la cholécystite aiguë","contenu":"<p>Complications septiques de la <span class=\"kw-clinique\">cholécystite</span> aiguë — <strong>par ordre chronologique d’aggravation</strong> :</p>\n      <ol>\n        <li><strong><span class=\"kw-alerte\">Empyème vésiculaire</span></strong> (pyocholécyste) — <span class=\"kw-clinique\">vésicule</span> sous tension remplie de pus, encore contenue par la paroi</li>\n        <li><strong><span class=\"kw-alerte\">Gangrène vésiculaire</span></strong> — <span class=\"kw-clinique\">nécrose</span> de la paroi vésiculaire (signe d’ischémie)</li>\n        <li><strong><span class=\"kw-alerte\">Perforation</span></strong> de la paroi → <span class=\"kw-alerte\">abcès péri-vésiculaire</span> ou <span class=\"kw-alerte\">abcès hépatique</span> de contiguïté</li>\n        <li><strong><span class=\"kw-alerte\">Péritonite biliaire</span></strong> — diffusion au péritoine, localisée puis généralisée (<span class=\"kw-alerte\">urgence</span> chirurgicale absolue)</li>\n      </ol>\n      <div class=\"callout callout-info\"><strong>Pour mémoire (hors référentiel).</strong> <span class=\"kw-alerte\">Iléus biliaire</span> (occlusion par <span class=\"kw-def\">fistule bilio-digestive</span>, <span class=\"kw-def\">terrain</span> âgé) et <span class=\"kw-etio\">syndrome de Mirizzi</span> (gros calcul du collet comprimant la VBP → <span class=\"kw-clinique\">cholécystite + ictère</span>) sont des complications plus rares.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</em></p>","frequence":0},{"id":"277-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","contenu":"<p>L’<strong><span class=\"kw-clinique\">angiocholite</span> aiguë</strong> est une <span class=\"kw-alerte\">infection aiguë de la voie biliaire principale</span> (germes digestifs : <span class=\"kw-etio\">BGN</span>, plus rarement coques Gram +), le plus souvent par enclavement d’un calcul.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Triade de Charcot</span>.</strong> Apparition successive en <span class=\"kw-chiffre\">48 h</span> (ordre chronologique, parfois incomplète) : 1. <span class=\"kw-clinique\">douleur biliaire</span> → 2. <span class=\"kw-clinique\">fièvre/frissons</span> (souvent au 1ᵉʳ plan, peut être sévère : <span class=\"kw-clinique\">bactériémie</span>, <span class=\"kw-alerte\">choc</span>) → 3. <span class=\"kw-clinique\">ictère</span> (survient après la douleur ; son absence n’écarte pas le diagnostic).</div>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Étiologies</strong></td><td>Enclavement d’un calcul dans la VBP ; sténose de la VBP (tumeur, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-etio\">pancréatite chronique</span>) ; parasites migrants (distomatose, ascaridiose)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">Syndrome inflammatoire/infectieux</span> ; <span class=\"kw-bio\">cholestase ictérique</span> (<span class=\"kw-bio\">bilirubine</span> à prédominance conjuguée) ; <span class=\"kw-bio\">cytolyse hépatique</span> fréquente en phase aiguë</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td><td><span class=\"kw-clinique\">Lithiase vésiculaire</span> ; paroi épaisse ; <span class=\"kw-radio\">dilatation de la VBP</span> (<span class=\"kw-alerte\">inconstante</span>) ; calcul de la VBP (Se <span class=\"kw-chiffre\">30-50 %</span>)</td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td><span class=\"kw-bio\">Hémocultures systématiques</span> (souvent positives à germes digestifs)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 281 — <span class=\"kw-clinique\">Pancréatite chronique</span></em></p>","frequence":3},{"id":"277-24","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","contenu":"<div class=\"callout callout-info\"><strong>1ʳᵉ intention.</strong> L’<strong><span class=\"kw-imagerie\">échographie abdominale</span></strong> est l’examen de <span class=\"kw-chiffre\">première intention</span>, en <span class=\"kw-alerte\">urgence</span>, devant une <span class=\"kw-clinique\">angiocholite</span> (recherche de lithiase, <span class=\"kw-radio\">dilatation de la VBP</span> — inconstante).</div>\n      <p>Examens de seconde intention pour la VBP : <span class=\"kw-imagerie\">scanner</span> (signes indirects), <span class=\"kw-imagerie\">cholangio-IRM</span> et <span class=\"kw-imagerie\">écho-endoscopie</span> (Se &gt; <span class=\"kw-chiffre\">90 %</span> pour la <span class=\"kw-etio\">lithiase de la VBP</span>).</p>","frequence":0},{"id":"277-25","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les trois évolutions possibles de l’angiocholite","contenu":"<p>Trois évolutions/complications graves de l’<span class=\"kw-clinique\">angiocholite</span> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Abcès hépatique</span></li>\n        <li><span class=\"kw-alerte\">Choc septique</span> / <span class=\"kw-alerte\">défaillance multiviscérale</span></li>\n        <li><span class=\"kw-alerte\">Angiocholite ictéro-urémigène</span> (associée à une <span class=\"kw-clinique\">insuffisance rénale</span>)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":0},{"id":"277-26","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","contenu":"<div class=\"callout callout-danger\"><strong>Ordre des priorités.</strong> En cas de <span class=\"kw-alerte\">sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">mesures de réanimation</span> passent en premier ; la <span class=\"kw-ttt\">CPRE</span> de désobstruction de la VBP n’est réalisée qu’<strong>après</strong> les mesures réanimatoires.</div>\n      <p>En <span class=\"kw-bio\">complément</span> : <span class=\"kw-ttt\">antibiothérapie</span> ; désobstruction de la VBP <span class=\"kw-chiffre\">&lt; 24 h</span> (<span class=\"kw-imagerie\">CPRE</span> 1ʳᵉ intention, ou <span class=\"kw-ttt\">drainage transcutané</span> des voies biliaires si CPRE non disponible en <span class=\"kw-alerte\">urgence</span> ou patient instable).</p>","frequence":0},{"id":"277-27","rang":"B","rubrique":"Prise en charge","titre":"Connaître les deux principes du traitement de l’angiocholite aiguë et les modalités de la cholangiopancréatographie rétrograde endoscopique (CPRE)","contenu":"<p><strong>Deux principes :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou <span class=\"kw-ttt\">C3G + imidazolé</span> pendant <span class=\"kw-chiffre\">7 jours</span> (+ traitement symptomatique)</li>\n        <li><strong>Désobstruction de la VBP en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>) :</strong> <span class=\"kw-ttt\">CPRE</span> en 1ʳᵉ intention ; <span class=\"kw-ttt\">drainage transcutané</span> si <span class=\"kw-imagerie\">CPRE</span> non disponible ou patient instable</li>\n      </ul>\n      <p><strong>Modalités de la <span class=\"kw-imagerie\">CPRE</span></strong> (geste endoscopique sous AG) :</p>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Déroulement</strong></td><td>Abord de la VBP ; <span class=\"kw-ttt\">sphinctérotomie endoscopique</span> du sphincter d’Oddi ; extraction instrumentale du calcul</td></tr>\n          <tr><td><strong>Complications</strong> (<span class=\"kw-chiffre\">5-10 %</span>)</td><td><span class=\"kw-etio\">Pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>, liée au PDC) ; <span class=\"kw-alerte\">hémorragie</span> (<span class=\"kw-chiffre\">1 %</span>) ; <span class=\"kw-alerte\">infection</span> ; <span class=\"kw-alerte\">perforation duodénale</span> (<span class=\"kw-chiffre\">0,1-0,6 %</span>)</td></tr>\n          <tr><td><strong>Inconvénients</strong></td><td>Examen coûteux, invasif ; n’est plus réalisée à visée purement diagnostique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Cholécystectomie (après désobstruction).</strong> <span class=\"kw-clinique\">Angiocholite</span> non sévère → durant la <span class=\"kw-chiffre\">même hospitalisation</span> ; angiocholite sévère → à distance, <span class=\"kw-chiffre\">&gt; 1 mois</span> ; parfois <span class=\"kw-alerte\">non réalisée</span> selon le <span class=\"kw-def\">terrain</span> du malade (comorbidités, âge physiologique).</div>","frequence":2},{"id":"277-28","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens paracliniques pouvant être réalisés à la recherche d’un calcul de la voie biliaire principale (VBP)","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Performance</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Échographie</span></td><td>1ʳᵉ intention mais <span class=\"kw-alerte\">peu sensible</span> pour le calcul cholédocien (<span class=\"kw-chiffre\">Se 30-50 %</span>) ; montre la <span class=\"kw-radio\">dilatation de la VBP</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Bili-IRM (cholangio-IRM)</span></td><td>Très sensible (<span class=\"kw-chiffre\">Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Écho-endoscopie</span></td><td>Très sensible (<span class=\"kw-chiffre\">Se &gt; 90 %</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Cholangiographie per-opératoire</span></td><td>Examen sensible ; réalisée pendant la cholécystectomie</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span></td><td>Valeur diagnostique <span class=\"kw-alerte\">inférieure</span> à la bili-<span class=\"kw-imagerie\">IRM</span> et à l’<span class=\"kw-imagerie\">écho-endoscopie</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"277-29","rang":"B","rubrique":"Prise en charge","titre":"Connaître les deux traitements possibles pour désobstruer la VBP en dehors de l’urgence septique","contenu":"<p><span class=\"kw-etio\">Lithiase de la VBP</span> <span class=\"kw-clinique\">sans angiocholite ni pancréatite</span> — deux options de désobstruction :</p>\n      <ul>\n        <li><strong>Désobstruction chirurgicale en 1 temps :</strong> <span class=\"kw-ttt\">cholécystectomie</span> avec <span class=\"kw-ttt\">désobstruction peropératoire de la VBP</span></li>\n        <li><strong>Désobstruction endoscopique en 2 temps :</strong> <span class=\"kw-ttt\">sphinctérotomie endoscopique</span> biliaire, puis <span class=\"kw-ttt\">cholécystectomie</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Angiocholite</span> aiguë</strong></p><p><span class=\"kw-ttt\">CPRE</span> de désobstruction de la <span class=\"kw-def\">VBP</span> en <span class=\"kw-chiffre\">&lt; 24 h</span>. Si <span class=\"kw-alerte\">sepsis sévère</span>/<span class=\"kw-alerte\">choc</span>, <span class=\"kw-alerte\">réanimation AVANT</span> la <span class=\"kw-ttt\">CPRE</span></p><ul><li><span class=\"kw-alerte\">urgence vitale</span></li></ul><p><strong><span class=\"kw-clinique\">Cholécystite</span> aiguë</strong></p><p><span class=\"kw-ttt\">cholécystectomie</span> en <span class=\"kw-alerte\">urgence</span> par <span class=\"kw-ttt\">cœlioscopie</span> en <span class=\"kw-chiffre\">&lt; 72 h</span></p><p><strong><span class=\"kw-clinique\">Pancréatite aiguë</span> biliaire</strong></p><ul><li>hospit + <span class=\"kw-ttt\">cholécystectomie</span> même <span class=\"kw-alerte\">hospitalisation</span> si <em><span class=\"kw-def\">PA minime</span></em></li><li>retardée à <span class=\"kw-chiffre\">3-6 semaines</span> si <em><span class=\"kw-alerte\">PA sévère/nécrosante</span></em></li></ul><p><strong><span class=\"kw-clinique\">Colique hépatique</span> / migration</strong></p><ul><li><span class=\"kw-ttt\">antalgie</span> en <span class=\"kw-alerte\">urgence</span> par voie parentérale</li><li><span class=\"kw-ttt\">cholécystectomie</span> programmée <span class=\"kw-chiffre\">&lt; 1 mois</span> après la crise</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-def\">colique hépatique simple</span> une fois la crise calmée (programmation chir <span class=\"kw-chiffre\">&lt; 1 mois</span>) ; <span class=\"kw-def\">migration lithiasique</span> non compliquée.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle :</strong> <span class=\"kw-def\">cholécystite aiguë</span> ; <span class=\"kw-def\">angiocholite non sévère</span> ; <span class=\"kw-def\">pancréatite aiguë biliaire</span> (selon <span class=\"kw-def\">Balthazar</span>).<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-def\">angiocholite</span> avec <span class=\"kw-alerte\">sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span> ; <span class=\"kw-alerte\">pancréatite aiguë sévère/nécrosante</span> ; <span class=\"kw-alerte\">défaillance multiviscérale</span>.<br><strong>Bloc en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-def\">cholécystite</span> (<span class=\"kw-chiffre\">&lt; 72 h</span>) ; <span class=\"kw-alerte\">péritonite biliaire</span> (<span class=\"kw-alerte\">perforation</span>) ; <span class=\"kw-alerte\">iléus biliaire</span> (<span class=\"kw-ttt\">incision-extraction</span>).<br><strong>Endoscopie interventionnelle :</strong> <span class=\"kw-ttt\">CPRE</span> pour <span class=\"kw-def\">angiocholite</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>) ou <span class=\"kw-def\">lithiase de la VBP</span> (à distance hors urgence septique).</p>","redflags":"<ul><li><strong><span class=\"kw-clinique\">Triade de Charcot</span> :</strong> <span class=\"kw-clinique\">douleur biliaire</span> → <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">frissons</span> → <span class=\"kw-clinique\">ictère</span> (apparition en <span class=\"kw-chiffre\">&lt; 48 h</span> ; signe une <span class=\"kw-def\">angiocholite</span>)</li><li><strong><span class=\"kw-clinique\">Sepsis</span> sévère / <span class=\"kw-alerte\">choc septique</span> :</strong> <span class=\"kw-alerte\">hypoTA</span>, <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">oligurie</span>, <span class=\"kw-bio\">lactates</span> ↑ — réa avant <span class=\"kw-ttt\">CPRE</span></li><li><strong><span class=\"kw-clinique\">Angiocholite</span> ictéro-urémigène :</strong> <span class=\"kw-alerte\">insuffisance rénale</span> associée (3ᵉ <span class=\"kw-clinique\">évolution</span> possible de l'<span class=\"kw-def\">angiocholite</span>)</li><li><strong>Défense / contracture abdominale :</strong> <span class=\"kw-alerte\">cholécystite grave</span>, <span class=\"kw-alerte\">perforation</span>, <span class=\"kw-alerte\">péritonite biliaire</span></li><li><strong>Douleur biliaire persistante &gt;<span class=\"kw-chiffre\"> 6-24 h</span> :</strong> élimine la <span class=\"kw-def\">colique simple</span>, oriente vers une complication (<span class=\"kw-def\">cholécystite a minima</span>)</li><li><strong><span class=\"kw-clinique\">Ictère</span> + <span class=\"kw-clinique\">fièvre</span> :</strong> évoque l'<span class=\"kw-def\">angiocholite</span> jusqu'à preuve du contraire (ne JAMAIS attendre la <span class=\"kw-def\">triade complète</span>)</li><li><strong><span class=\"kw-bio\">Lipase</span> <span class=\"kw-chiffre\">≥ 3</span> N + douleur transfixiante permanente :</strong> <span class=\"kw-def\">pancréatite aiguë biliaire</span> (vérifier <span class=\"kw-def\">Balthazar</span> / <span class=\"kw-def\">score de Ranson</span> / <span class=\"kw-def\">BISAP</span>)</li><li><strong>Aérobilie sur <span class=\"kw-imagerie\">TDM</span></strong> + <span class=\"kw-clinique\">syndrome occlusif</span> chez le <span class=\"kw-etio\">sujet âgé</span> : <span class=\"kw-def\">iléus biliaire</span> (<span class=\"kw-def\">fistule bilio-digestive</span>)</li><li><strong><span class=\"kw-bio\">Hémocultures</span> positives à BGN :</strong> <span class=\"kw-etio\">origine biliaire</span> à rechercher systématiquement</li></ul>","principes":"<p>Quatre piliers communs (modulés selon l'entité) : <span class=\"kw-ttt\">antalgie parentérale</span> → <span class=\"kw-ttt\">antibiothérapie</span> (si infection) → désobstruction de la <span class=\"kw-def\">VBP</span> (<span class=\"kw-ttt\">CPRE</span> ou <span class=\"kw-ttt\">drainage</span>) → <span class=\"kw-ttt\">cholécystectomie cœlioscopique</span> (délai entité-dépendant).</p><p><strong>Antalgie / symptomatique</strong></p><ul><li>voie parentérale en <span class=\"kw-alerte\">urgence</span> — <span class=\"kw-ttt\">antispasmodiques</span> (<span class=\"kw-ttt\">phloroglucinol</span> ou <span class=\"kw-ttt\">trimébutine</span>) + <span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-ttt\">AINS</span> <span class=\"kw-ci\">en l'absence de CI</span> ± <span class=\"kw-ttt\">remplissage</span></li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> <span class=\"q\">(<span class=\"kw-def\">cholécystite</span> et <span class=\"kw-def\">angiocholite</span> uniquement, PAS pour <span class=\"kw-def\">colique</span>/<span class=\"kw-def\">migration</span>/<span class=\"kw-def\">PA non compliquée</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> OU <span class=\"kw-ttt\">C3G + imidazolé</span> pendant <span class=\"kw-chiffre\">7 jours</span></li></ul><p><strong>Désobstruction de la VBP en <span class=\"kw-alerte\">urgence</span> <span class=\"q\">(<span class=\"kw-clinique\">angiocholite</span> &lt;<span class=\"kw-chiffre\"> 24 h</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">CPRE</span> avec <span class=\"kw-ttt\">sphinctérotomie endoscopique d'Oddi</span> en 1ʳᵉ intention</li><li><span class=\"kw-ttt\">drainage transcutané</span> sous guidage écho si <span class=\"kw-ttt\">CPRE</span> non disponible en <span class=\"kw-alerte\">urgence</span> OU patient instable (nécessite <span class=\"kw-imagerie\">VB intra-hépatiques très dilatées</span>)</li></ul><p><strong>Désobstruction hors <span class=\"kw-alerte\">urgence</span> septique <span class=\"q\">(<span class=\"kw-clinique\">lithiase de la VBP</span> isolée)</span></strong></p><ul><li>soit <em>chirurgicale en 1 temps</em> (<span class=\"kw-ttt\">cholécystectomie</span> + <span class=\"kw-ttt\">désobstruction peropératoire de la VBP</span>)</li><li>soit <em>endoscopique en 2 temps</em> (<span class=\"kw-ttt\">sphinctérotomie endoscopique biliaire</span>, puis <span class=\"kw-ttt\">cholécystectomie</span>)</li></ul><p><strong>Cholécystectomie cœlioscopique <span class=\"q\">(laparoscopique) — délai entité-dépendant</span></strong></p><ul><li><span class=\"kw-def\">colique</span>/<span class=\"kw-def\">migration</span> <span class=\"kw-chiffre\">&lt; 1 mois</span></li><li><span class=\"kw-def\">cholécystite</span> <span class=\"kw-chiffre\">&lt; 72 h</span></li><li><span class=\"kw-def\">angiocholite non sévère</span> = même <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-alerte\">angiocholite sévère</span> = à distance <span class=\"kw-chiffre\">&gt; 1 mois</span> (parfois <strong>non réalisée</strong> selon <span class=\"kw-def\">terrain</span>)</li><li><span class=\"kw-def\">PA biliaire minime</span> = même hospit, <span class=\"kw-alerte\">PA nécrosante</span> = <span class=\"kw-chiffre\">3-6 semaines</span></li></ul>","suivi":"<p><strong>Post-<span class=\"kw-imagerie\">CPRE</span> :</strong> <span class=\"kw-def\">surveillance</span> des complications (<span class=\"kw-chiffre\">5-10 %</span>) — <span class=\"kw-alerte\">pancréatite aiguë</span> (<span class=\"kw-chiffre\">5 %</span>, liée au <span class=\"kw-imagerie\">PDC</span>), <span class=\"kw-alerte\">hémorragie</span> (<span class=\"kw-chiffre\">1 %</span>), <span class=\"kw-alerte\">infection</span>, <span class=\"kw-alerte\">perforation duodénale</span> (<span class=\"kw-chiffre\">0,1-0,6 %</span>).<br><strong>Post-cholécystectomie :</strong> reprise précoce de l'alimentation ; surveillance de la cicatrisation ; pas de <span class=\"kw-def\">prévention secondaire</span> spécifique (récidive rare).<br><strong>Cholécystectomie systématique post-cure</strong> de toute <span class=\"kw-def\">lithiase symptomatique/compliquée</span> pour éviter la récidive (sauf <span class=\"kw-def\">terrain</span> contre-indiquant la chir : <span class=\"kw-etio\">comorbidités</span>, <span class=\"kw-etio\">âge physiologique</span>).<br><strong>Lithiase VBP résiduelle :</strong> à dépister si tableau persistant — <span class=\"kw-imagerie\">bili-IRM</span> ou <span class=\"kw-imagerie\">écho-endoscopie</span> (<span class=\"kw-chiffre\">Se &gt; 90 %</span>).<br><strong>Reconsultation</strong> immédiate si récidive de <span class=\"kw-clinique\">douleur biliaire</span>, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">ictère</span> ou <span class=\"kw-clinique\">syndrome occlusif</span> (<span class=\"kw-def\">iléus biliaire</span> à distance).</p>"},"liensGlobaux":[{"href":"https://moodle.umontpellier.fr/pluginfile.php/1394203/mod_folder/content/0/voie%20biliaires%20-%20r%C3%A9um%C3%A9.pdf","label":"Voie biliaires   réumé"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de lithiase biliaire symptomatique — Douleur biliaire (épigastre/HCD, brutale, irradiation omoplate) ± fièvre ± ictère","detail":"<h4>CAT — Lithiase biliaire symptomatique — Discrimination des 5 entités cliniques et orientation thérapeutique</h4>","branches":[{"to":"q-migr","label":"Douleur < 6 h","color":"green"},{"to":"q-fievre","label":"Douleur > 6 h","color":"amber"}]},{"id":"q-migr","kind":"decision","label":"Élévation transitoire des transaminases (↓ <span class=\"kw-chiffre\">> 50 %</span> en <span class=\"kw-chiffre\">< 48</span> h) ? — Cinétique = meilleur signe ; écho souvent identique à une colique simple","branches":[{"to":"t-migration","label":"Oui (pic transaminases ; γ-GT/bili N)","color":"amber"},{"to":"t-colique","label":"Non (bilan normal)","color":"green"}]},{"id":"t-migration","kind":"terminal","label":"Migration lithiasique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Colique hépatique</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">6 h</span></span> ; pas de <span class=\"kw-clinique\">fièvre</span> ; pas d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li>Élévation transitoire des <span class=\"kw-bio\">transaminases</span> (↓ > <span class=\"kw-chiffre\">50 %</span> en < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>) ; <span class=\"kw-bio\">bilirubine</span> et <span class=\"kw-bio\">γ-GT</span> normales</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie abdominale</span> (<span class=\"kw-chiffre\">Se médiocre</span> pour le calcul cholédocien) ; <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> en 2ᵉ intention si doute</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgie parentérale</span> (<span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> ± <span class=\"kw-ttt\">AINS</span>)</li><li><span class=\"kw-ci\">Pas d'antibiothérapie</span></li><li><span class=\"kw-ttt\">Cholécystectomie cœlioscopique</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span> après la crise</li></ul><h4>Délai</h4><ul><li>Crise calmée → ambu ; <span class=\"kw-ttt\">chirurgie</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span></li></ul>"},{"id":"t-colique","kind":"terminal","label":"Colique hépatique simple","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur biliaire</span> brutale < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">6 h</span></span> ; <span class=\"kw-clinique\">signe de Murphy</span> ; PAS de <span class=\"kw-clinique\">fièvre</span>, PAS d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li>Aucune anomalie (<span class=\"kw-bio\">bilan hépatique</span> normal, pas de <span class=\"kw-bio\">syndrome inflammatoire</span>)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> (<span class=\"kw-chiffre\">Se 95 %</span> pour calculs vésiculaires) — <span class=\"kw-imagerie\">calculs hyperéchogènes</span>, <span class=\"kw-imagerie\">cône d'ombre</span>, <span class=\"kw-imagerie\">mobiles</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgie parentérale</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> ± <span class=\"kw-ttt\">AINS</span> hors CI)</li><li><span class=\"kw-ttt\">Cholécystectomie cœlioscopique</span> programmée < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 mois</span></span> après la crise (prévention récidive/complication)</li></ul><h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-def\">SCA</span> · <span class=\"kw-def\">UGD</span> · <span class=\"kw-def\">pancréatite aiguë</span></li></ul>"},{"id":"q-fievre","kind":"decision","label":"Fièvre / syndrome infectieux ? — Fièvre = élimine la colique simple, oriente vers infection biliaire","branches":[{"to":"q-pa","label":"Non (apyrétique)","color":"amber"},{"to":"q-ictere","label":"Oui (fièvre + frissons)","color":"red"}]},{"id":"q-pa","kind":"decision","label":"Douleur transfixiante permanente + lipase ≥ 3 N ? — Critères biologiques de pancréatite aiguë","branches":[{"to":"t-pa","label":"Oui (lipase ≥ 3 N)","color":"amber"},{"to":"t-atypique","label":"Non (lipase normale)","color":"blue"}]},{"id":"t-pa","kind":"terminal","label":"Pancréatite aiguë biliaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur transfixiante et permanente</span> ; <span class=\"kw-clinique\">fièvre</span> ± ; pas d'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Lipase ≥ 3 N</span> ; pic précoce et transitoire des <span class=\"kw-bio\">transaminases</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>, <span class=\"kw-bio\">ASAT</span> prédomine d'abord puis <span class=\"kw-bio\">ALAT</span>) ; <span class=\"kw-bio\">bilirubine totale</span> > <span class=\"kw-chiffre\">40 µmol/L</span> = <span class=\"kw-def\">blocage ampullaire</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> en <span class=\"kw-alerte\">urgence</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>) ; <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> si doute. Arguments d'origine biliaire : <span class=\"kw-imagerie\">calculs vésiculaires</span> petits (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">3 mm</span></span>) et nombreux (<span class=\"kw-chiffre\">≥ 4</span>), <span class=\"kw-imagerie\">canal cystique large</span>, <span class=\"kw-imagerie\">dilatation VBP</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">antalgie</span></li><li><span class=\"kw-ci\">Pas d'antibiothérapie systématique</span></li><li><span class=\"kw-ttt\">CPRE</span> seulement si suspicion d'<span class=\"kw-def\">angiocholite</span> associée (<span class=\"kw-alerte\">urgence</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">24 h</span></span>) ou de <span class=\"kw-def\">calcul VBP résiduel</span> (à distance)</li><li><span class=\"kw-ttt\">Cholécystectomie</span> systématique : même <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-def\">PA minime</span> ; à <span class=\"kw-chiffre\">3-6 semaines</span> si <span class=\"kw-alerte\">PA sévère/nécrosante</span></li></ul><h4>Renvoi</h4><ul><li>Item 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span></li></ul>"},{"id":"t-atypique","kind":"terminal","label":"Douleur biliaire prolongée atypique — réévaluer","color":"blue","detail":"<h4>Conduite</h4><ul><li>Pas de tableau franc des 5 entités lithiasiques ; reprendre interrogatoire, refaire bilan à <span class=\"kw-chiffre\">H+6</span> (<span class=\"kw-bio\">transaminases</span>, <span class=\"kw-bio\">lipase</span>, <span class=\"kw-bio\">CRP</span>), refaire <span class=\"kw-imagerie\">échographie</span></li></ul><h4>Diagnostics différentiels à éliminer</h4><ul><li><span class=\"kw-def\">SCA</span> (<span class=\"kw-clinique\">épigastralgie</span> trompeuse)</li><li><span class=\"kw-def\">UGD compliqué</span></li><li><span class=\"kw-def\">Cholécystite a minima</span> (<span class=\"kw-imagerie\">paroi > 4 mm</span> ?)</li><li>Autre cause d'<span class=\"kw-clinique\">abdomen aigu</span></li></ul><h4>Renvois</h4><ul><li>Item 269 — Douleur abdominale aiguë · Item 339 — <span class=\"kw-alerte\">SCA</span> · Item 272 — <span class=\"kw-clinique\">UGD</span></li></ul>"},{"id":"q-ictere","kind":"decision","label":"Ictère ± dilatation VBP à l'échographie ? — Triade de Charcot = douleur + fièvre + ictère (en 48 h, parfois incomplète)","branches":[{"to":"t-angio","label":"Oui (triade ± complète, dilatation VBP)","color":"red"},{"to":"t-cholecy","label":"Non (pas d'ictère, pas de dilatation VBP)","color":"amber"}]},{"id":"t-angio","kind":"terminal","label":"Angiocholite aiguë","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Triade de Charcot</span> : <span class=\"kw-clinique\">douleur biliaire</span> → <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">frissons</span> → <span class=\"kw-clinique\">ictère</span> (apparition en < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>, ordre chronologique ; absence d'<span class=\"kw-clinique\">ictère</span> n'écarte PAS le diagnostic)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire/infectieux</span> ; <span class=\"kw-bio\">cholestase ictérique</span> (<span class=\"kw-bio\">bilirubine conjuguée</span>) ; <span class=\"kw-bio\">cytolyse hépatique</span> ; <span class=\"kw-bio\">hémocultures</span> systématiques (<span class=\"kw-etio\">BGN</span> d'origine digestive)</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-imagerie\">lithiase vésiculaire</span>, <span class=\"kw-imagerie\">paroi épaisse</span>, <span class=\"kw-imagerie\">dilatation VBP</span> inconstante, <span class=\"kw-imagerie\">calcul VBP</span> <span class=\"kw-chiffre\">Se 30-50 %</span>) ; 2ᵉ intention <span class=\"kw-imagerie\">bili-IRM</span> / <span class=\"kw-imagerie\">écho-endoscopie</span> (<span class=\"kw-chiffre\">Se > 90 %</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> OU <span class=\"kw-ttt\">C3G + imidazolé</span> × <span class=\"kw-chiffre\">7 j</span></li><li><span class=\"kw-ttt\">CPRE</span> avec <span class=\"kw-ttt\">sphinctérotomie endoscopique</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">24 h</span></span> (1ʳᵉ intention)</li><li><span class=\"kw-ttt\">Drainage transcutané</span> sous guidage écho si <span class=\"kw-ttt\">CPRE</span> non disponible OU patient instable</li><li>⚠️ Si <span class=\"kw-alerte\">sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span> : <span class=\"kw-alerte\">RÉANIMATION</span> (<span class=\"kw-ttt\">remplissage</span>, <span class=\"kw-ttt\">vasopresseurs</span>, <span class=\"kw-bio\">hémocultures</span>) AVANT la <span class=\"kw-ttt\">CPRE</span></li><li><span class=\"kw-ttt\">Cholécystectomie</span> après <span class=\"kw-ttt\">CPRE</span> : même <span class=\"kw-alerte\">hospitalisation</span> si non sévère ; > <span class=\"kw-chiffre\">1 mois</span> si sévère ; parfois non réalisée selon <span class=\"kw-def\">terrain</span></li></ul><h4>3 évolutions possibles</h4><ul><li><span class=\"kw-alerte\">Abcès hépatique</span></li><li><span class=\"kw-alerte\">Choc septique</span> / <span class=\"kw-alerte\">défaillance multiviscérale</span></li><li><span class=\"kw-alerte\">Angiocholite ictéro-urémigène</span> (<span class=\"kw-alerte\">insuffisance rénale</span>)</li></ul><h4>Renvois</h4><ul><li>Item 158 — <span class=\"kw-clinique\">Sepsis</span> · Item 278 — <span class=\"kw-clinique\">Ictère</span> · Item 281 — <span class=\"kw-clinique\">Pancréatite chronique</span> (sténose VBP)</li></ul>"},{"id":"t-cholecy","kind":"terminal","label":"Cholécystite aiguë","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> > <span class=\"kw-chiffre\">6 h</span> (souvent > <span class=\"kw-chiffre\">24 h</span>) ; <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span> ; PAS d'<span class=\"kw-clinique\">ictère</span> (sauf <span class=\"kw-def\">syndrome de Mirizzi</span>) ; <span class=\"kw-alerte\">signes d'irritation péritonéale</span> possibles si forme grave</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">PNN</span>, <span class=\"kw-bio\">CRP</span>/<span class=\"kw-bio\">PCT</span>) ; <span class=\"kw-bio\">bilan hépatique</span> normal ; <span class=\"kw-bio\">lipase</span> normale</li></ul><h4>Imagerie</h4><ul><li>1ʳᵉ intention = <span class=\"kw-imagerie\">échographie</span> : <span class=\"kw-imagerie\">paroi > 4 mm en triple feuillet</span>, <span class=\"kw-imagerie\">distension > 4 cm</span>, <span class=\"kw-imagerie\">calcul vésiculaire</span>, <span class=\"kw-imagerie\">Murphy échographique</span>. 2ʳᵉ intention = <span class=\"kw-imagerie\">scanner</span> si doute</li></ul><h4>Traitement</h4><ul><li>Symptomatique : <span class=\"kw-ttt\">remplissage</span> + <span class=\"kw-ttt\">phloroglucinol</span>/<span class=\"kw-ttt\">trimébutine</span> + <span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-ttt\">AINS</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">Augmentin</span> OU <span class=\"kw-ttt\">C3G + imidazolé</span> × <span class=\"kw-chiffre\">7 j</span></li><li><span class=\"kw-ttt\">Cholécystectomie</span> en <span class=\"kw-alerte\">URGENCE</span> par <span class=\"kw-ttt\">cœlioscopie</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72 h</span></span></li></ul><h4>Complications septiques (ordre d'aggravation)</h4><ul><li><span class=\"kw-alerte\">Empyème vésiculaire</span></li><li><span class=\"kw-alerte\">Gangrène vésiculaire</span></li><li><span class=\"kw-alerte\">Perforation</span> → <span class=\"kw-alerte\">abcès péri-vésiculaire / hépatique</span></li><li><span class=\"kw-alerte\">Péritonite biliaire</span> (localisée puis généralisée)</li></ul><h4>Renvoi</h4><ul><li>Item 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë</li></ul>"}]},"cards":[{"i":"2cd7b75add0d","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce qu'une cholécystite aiguë et quel est son mécanisme ?","a":"<p>La cholécystite aiguë est une <strong>infection aiguë</strong> de la vésicule biliaire, résultant d'une <strong>obstruction prolongée du canal cystique</strong> par un calcul.</p>"},{"i":"366d9b6139d7","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quelle est la définition d'une lithiase biliaire ?","a":"<p>La lithiase biliaire est définie par la présence de <strong>calculs</strong> formés à partir de la <strong>bile</strong>.</p>"},{"i":"4219f1427f47","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce qu'une lithiase vésiculaire et quelle est sa fréquence symptomatique ?","a":"<p>La lithiase vésiculaire correspond à la présence d'un calcul formé à partir de la bile, localisé dans la <strong>vésicule biliaire</strong>. Elle est la forme la plus fréquente de lithiase biliaire et est asymptomatique dans <strong>80 %</strong> des cas.</p>"},{"i":"5d2ce9ee0d28","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quelle est la définition et le mécanisme de l'angiocholite ?","a":"<p>L'angiocholite est une <strong>infection bactérienne</strong> de la voie biliaire principale (VBP), causée par l'<strong>enclavement d'un calcul</strong> au niveau de l'ampoule de Vater.</p>"},{"i":"8e12f8a7ea4a","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quel est l'impact d'une lithiase de la voie biliaire principale (VBP) ?","a":"<p>Une lithiase de la VBP correspond à la présence d'un calcul dans la voie biliaire principale. Si l'obstruction est prolongée, elle peut entraîner un <strong>ictère</strong>.</p>"},{"i":"b48a4dc7a2a9","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Comment se définit la colique hépatique dans le contexte de la lithiase biliaire ?","a":"<p>Une colique hépatique est une douleur causée par la <strong>mise en tension brutale des voies biliaires</strong>, secondaire au blocage transitoire d'un calcul au niveau du <strong>canal cystique</strong> ou de la <strong>voie biliaire principale (VBP)</strong>.</p>"},{"i":"bab87aafcdec","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Qu'est-ce que l'iléus biliaire ?","a":"<p>L'iléus biliaire est un <strong>syndrome occlusif</strong> causé par l'obstruction duodénale ou iléale par un <strong>calcul biliaire</strong>.</p>"},{"i":"c5eebda82491","n":277,"o":"277-1","u":"Définition","t":"Connaître la définition d’une lithiase biliaire et des différentes complications","q":"Quel est le mécanisme de la pancréatite aiguë lithiasique ?","a":"<p>La pancréatite aiguë lithiasique est une <strong>inflammation aiguë du pancréas</strong>, secondaire à la <strong>migration d'un calcul</strong> dans l'ampoule de Vater.</p>"},{"i":"d6a23850b4b4","n":277,"o":"277-10","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics différentiels à évoquer devant une colique hépatique","q":"Quels sont les trois principaux diagnostics différentiels à évoquer devant une colique hépatique ?","a":"<p>Devant une douleur épigastrique ou de l'hypochondre droit pouvant évoquer une colique hépatique, les trois diagnostics différentiels principaux à éliminer sont :</p><ul><li>Le <strong>syndrome coronarien aigu (SCA)</strong>, surtout si la douleur épigastrique est trompeuse.</li><li>L'<strong>ulcère gastro-duodénal (UGD)</strong>.</li><li>La <strong>pancréatite aiguë</strong>.</li></ul>"},{"i":"66433f3cf08f","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quel est le traitement médical de la crise de lithiase biliaire (colique hépatique) ?","a":"<p>En urgence, par voie parentérale, il comprend :</p><ul><li>Des <strong>antispasmodiques</strong> (par exemple, <strong>phloroglucinol</strong> ou <strong>trimébutine</strong>).</li><li>Des <strong>antalgiques</strong>, associés à des <strong>AINS</strong> en l'absence de contre-indication.</li></ul>"},{"i":"a3aa55aa647b","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quels sont les deux grands volets de la prise en charge de la lithiase biliaire symptomatique ?","a":"<p>Les deux grands volets de la prise en charge sont :</p><ul><li>Soulager la <strong>crise</strong>.</li><li>Prévenir la <strong>récidive</strong>.</li></ul>"},{"i":"dc0f8f1e1f17","n":277,"o":"277-12","u":"Prise en charge","t":"Connaître les principes du traitement de la pathologie lithiasique symptomatique","q":"Quel est le traitement préventif de la récidive et des complications de la lithiase biliaire symptomatique ?","a":"<p>Le traitement préventif de choix est la <strong>cholécystectomie</strong>. Idéalement réalisée sous <strong>cœlioscopie</strong>, elle est effectuée rapidement une fois la crise calmée, généralement dans le mois suivant (<strong>< 1 mois</strong>).</p>"},{"i":"744979bdfa74","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Quelle est la performance diagnostique de l'échographie abdominale pour les calculs vésiculaires ?","a":"<p>L'échographie abdominale présente une <strong>sensibilité de 95 %</strong> pour la détection des calculs vésiculaires. Elle est considérée comme supérieure au scanner (TDM) et à l'IRM pour cette indication.</p>"},{"i":"810f2b700fac","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Dans quelles situations le scanner abdominal ou la bili-IRM sont-ils envisagés en seconde intention pour une lithiase biliaire ?","a":"<p>Le scanner abdominal ou la bili-IRM peuvent être discutés en seconde intention dans l'exploration d'une lithiase biliaire, notamment pour confirmer certaines complications de la lithiase biliaire. Ils n'ont <strong>pas d'indication</strong> en cas de <strong>calcul vésiculaire isolé</strong>.</p>"},{"i":"f8e24bbf4773","n":277,"o":"277-13","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une lithiase biliaire","q":"Quel est l'examen d'imagerie de première intention pour l'exploration d'une lithiase biliaire symptomatique ?","a":"<p>L'examen de première intention pour explorer une lithiase biliaire symptomatique est l'<strong>échographie abdominale</strong>.</p>"},{"i":"42dfdd8a3af8","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Quel est le mécanisme d'une migration lithiasique dans le contexte d'une lithiase biliaire ?","a":"<p>La migration lithiasique correspond au passage de <strong>petits calculs</strong> de la vésicule biliaire vers la <strong>voie biliaire principale (VBP)</strong>. Ce phénomène est le plus souvent <strong>transitoire</strong>, les calculs étant ensuite évacués spontanément.</p>"},{"i":"6b3efa523c9a","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Comment l'échographie hépato-biliaire se présente-t-elle le plus souvent lors d'une migration lithiasique ?","a":"<p>L'échographie hépato-biliaire peut montrer :</p><ul><li>Des <strong>parois vésiculaires fines</strong>.</li><li>Une <strong>dilatation modérée et inconstante de la voie biliaire principale (VBP)</strong>.</li><li>Le <strong>calcul est rarement visualisé</strong> directement dans la VBP.</li></ul><p>Les images échographiques sont souvent similaires à celles d'une simple colique hépatique, d'où l'importance de la cinétique des transaminases.</p>"},{"i":"b926fa72910f","n":277,"o":"277-14","u":"Diagnostic positif","t":"Connaître le mécanisme et savoir diagnostiquer une migration lithiasique","q":"Quel est le signe biologique le plus discriminant d'une migration lithiasique ?","a":"<p>Le signe biologique le plus discriminant est l'<strong>élévation transitoire des transaminases</strong> (ASAT, ALAT). Leur particularité est de <strong>diminuer de plus de 50 % en moins de 48 heures</strong>. La bilirubine et les gamma-GT sont généralement normales ou n'ont pas encore eu le temps de s'élever.</p>"},{"i":"2c3e84680eee","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une suspicion de migration lithiasique dans le cadre d'un tableau de colique hépatique ?","a":"<p>L'examen de première intention est l'<strong>échographie abdominale</strong>.</p>"},{"i":"b70598ed888f","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Étant donné les limites de l'échographie, sur quel élément biologique repose majoritairement le diagnostic de migration lithiasique du cholédoque ?","a":"<p>Le diagnostic repose essentiellement sur l'<strong>élévation transitoire des transaminases</strong>.</p>"},{"i":"bd681324a1ae","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quelles sont les limites de l'échographie abdominale dans le diagnostic d'une migration lithiasique dans le cholédoque ?","a":"<ul><li>Elle met rarement en évidence la <strong>dilatation de la voie biliaire principale (VBP)</strong>.</li><li>Elle met rarement en évidence un <strong>calcul cholédocien</strong>.</li><li>Elle ne montre souvent que les <strong>calculs vésiculaires</strong> (dans la vésicule biliaire).</li></ul>"},{"i":"cc7df5a95cc0","n":277,"o":"277-15","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une migration lithiasique","q":"Quels sont les examens d'imagerie les plus performants pour visualiser un calcul cholédocien, et sont-ils réalisés en première intention ?","a":"<p>Les meilleurs examens pour voir un calcul cholédocien sont la <strong>bili-IRM</strong> et l'<strong>écho-endoscopie</strong>. Cependant, ils ne sont <strong>PAS utilisés en première intention</strong>.</p>"},{"i":"3aea3e5363c4","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quels sont les marqueurs biologiques clés et les anomalies échographiques en faveur du diagnostic de cholécystite aiguë ?","a":"<ul><li><strong>Biologie :</strong><ul><li>Un <span style=\"text-decoration:underline;\">syndrome inflammatoire</span> est présent, avec une <span style=\"text-decoration:underline;\">hyperleucocytose à PNN</span> (polynucléaires neutrophiles), une <span style=\"text-decoration:underline;\">élévation de la CRP</span> et/ou de la procalcitonine (PCT).</li><li>Le <span style=\"text-decoration:underline;\">bilan hépatique est habituellement normal</span>.</li><li>La <span style=\"text-decoration:underline;\">lipase est normale</span>.</li></ul></li><li><strong>Échographie :</strong><ul><li>Un <span style=\"text-decoration:underline;\">épaississement de la paroi vésiculaire</span> <span style=\"text-decoration:underline;\">supérieur à 4 mm</span>, souvent en triple feuillet.</li><li>Une <span style=\"text-decoration:underline;\">distension vésiculaire</span> <span style=\"text-decoration:underline;\">supérieure à 4 cm</span>.</li><li>La présence d'un ou plusieurs <span style=\"text-decoration:underline;\">calculs vésiculaires</span> (hyperéchogènes, mobiles, avec cône d'ombre postérieur).</li><li>Un <span style=\"text-decoration:underline;\">signe de Murphy échographique</span> positif, caractérisé par une douleur provoquée lors de la compression de la vésicule par la sonde d'échographie.</li></ul></li></ul>"},{"i":"68d635c2b77e","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quels sont les signes cliniques majeurs permettant de suspecter une cholécystite aiguë ?","a":"<ul><li>Une <span style=\"text-decoration:underline;\">colique hépatique persistante</span>, d'une durée <span style=\"text-decoration:underline;\">supérieure à 6 heures</span>, souvent même <span style=\"text-decoration:underline;\">supérieure à 24 heures</span>.</li><li>Un <span style=\"text-decoration:underline;\">syndrome infectieux fréquent</span>, caractérisé par de la <span style=\"text-decoration:underline;\">fièvre</span> et des <span style=\"text-decoration:underline;\">frissons</span>.</li><li>L'<span style=\"text-decoration:underline;\">absence d'ictère</span>, sauf en cas de syndrome de Mirizzi, atypique.</li><li>Des <span style=\"text-decoration:underline;\">signes d'irritation péritonéale locaux</span> sont possibles, notamment en cas de cholécystite grave.</li></ul>"},{"i":"f7c6db333207","n":277,"o":"277-16","u":"Diagnostic positif","t":"Savoir diagnostiquer une lithiase vésiculaire compliquée : cholécystite aiguë","q":"Quel est le mécanisme physiopathologique de la cholécystite aiguë lithiasique ?","a":"<p>La cholécystite aiguë lithiasique est causée par l'<span style=\"text-decoration:underline;\">obstruction prolongée du canal cystique par un calcul</span>. Cette obstruction entraîne une inflammation de la paroi vésiculaire, pouvant évoluer vers une infection aiguë de la vésicule biliaire.</p>"},{"i":"0318d655c6b4","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Quels sont les signes échographiques évocateurs d'une cholécystite aiguë ?","a":"<ul><li><strong>Épaississement de la paroi</strong> de la vésicule biliaire, mesurant <strong>plus de 4 mm</strong>, et d'aspect en <strong>triple feuillet</strong>.</li><li><strong>Distension</strong> de la vésicule biliaire, avec un diamètre supérieur à <strong>4 cm</strong>.</li><li>Présence d'un <strong>Murphy échographique</strong> (douleur déclenchée par la sonde d'échographie au niveau de la vésicule biliaire).</li></ul>"},{"i":"2d5af5681730","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Dans quelles situations un scanner abdominal est-il envisagé devant une cholécystite aiguë ?","a":"<p>Le scanner abdominal est envisagé en seconde intention dans les situations suivantes :</p><ul><li>En cas de <strong>doute diagnostique</strong>.</li><li>Pour rechercher ou évaluer des <strong>complications</strong> de la cholécystite aiguë.</li><li>En cas de <strong>contre-indication chirurgicale</strong>, pour une meilleure planification thérapeutique ou recherche d'alternatives non chirurgicales.</li></ul>"},{"i":"a9f70cc8e775","n":277,"o":"277-17","u":"Examens complémentaires","t":"Connaître l’indication des examens d’imagerie devant une cholécystite aiguë","q":"Quel est l'examen d'imagerie de première intention à réaliser devant une suspicion de cholécystite aiguë ?","a":"<p>L'examen d'imagerie de première intention est l'<strong>échographie abdominale</strong>.</p>"},{"i":"577ad3f56ef7","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quel est le traitement chirurgical de la cholécystite aiguë et dans quel délai doit-il être réalisé ?","a":"<p>Le traitement chirurgical de la cholécystite aiguë est la <strong>cholécystectomie en urgence</strong>, réalisée par <strong>voie laparoscopique/cœlioscopique</strong>. Elle doit être pratiquée idéalement dans les <strong>72 heures</strong> suivant le début des symptômes.</p>"},{"i":"c62c563eba47","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quelle est l'antibiothérapie recommandée pour la cholécystite aiguë et pour quelle durée ?","a":"<p>L'antibiothérapie recommandée pour la cholécystite aiguë est une association d'<strong>amoxicilline-acide clavulanique</strong> ou une <strong>C3G (céphalosporine de 3ème génération)</strong> associée à un <strong>imidazolé</strong>. La durée du traitement est de <strong>7 jours</strong>.</p>"},{"i":"e87cb43f8fda","n":277,"o":"277-20","u":"Prise en charge","t":"Connaître les principes du traitement de la cholécystite aiguë","q":"Quelle est la prise en charge symptomatique de la cholécystite aiguë ?","a":"<p>La prise en charge symptomatique de la cholécystite aiguë comprend :</p><ul><li>Un <strong>remplissage vasculaire</strong>.</li><li>Des antispasmodiques : <strong>phloroglucinol</strong> ou <strong>trimébutine</strong>.</li><li>Des <strong>antalgiques</strong>.</li><li>Des <strong>AINS</strong> (anti-inflammatoires non stéroïdiens).</li></ul>"},{"i":"3f28a6acbe4b","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quand parle-t-on de péritonite biliaire au cours de l'aggravation d'une cholécystite aiguë et quelle est sa prise en charge ?","a":"<p>La péritonite biliaire survient lorsque l'infection diffuse au péritoine, d'abord de manière localisée puis généralisée. C'est une <strong>urgence chirurgicale absolue</strong>.</p>"},{"i":"651f18111e5d","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quelle est la première complication septique de la cholécystite aiguë par ordre chronologique d'aggravation ?","a":"<p>La première complication est l'<strong>empyème vésiculaire</strong> ou <strong>pyocholécyste</strong>. Il s'agit d'une vésicule biliaire sous tension remplie de pus, mais encore contenue par sa paroi.</p>"},{"i":"8866f1939ae6","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Quelles sont les complications de la perforation de la paroi vésiculaire au cours d'une cholécystite aiguë ?","a":"<p>La perforation de la paroi vésiculaire peut entraîner un <strong>abcès péri-vésiculaire</strong> ou un <strong>abcès hépatique de contiguïté</strong>.</p>"},{"i":"fa2fc52f6111","n":277,"o":"277-22","u":"Suivi et / ou pronostic","t":"Connaître les complications septiques de la cholécystite aiguë","q":"Qu'est-ce que la gangrène vésiculaire dans le contexte des complications de la cholécystite aiguë ?","a":"<p>La gangrène vésiculaire est la <strong>nécrose de la paroi vésiculaire</strong>, qui est un signe d'ischémie.</p>"},{"i":"2fd43aacbc41","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Que peut révéler l'échographie abdominale en cas d'angiocholite aiguë ?","a":"<p>L'échographie peut mettre en évidence :</p><ul><li>Une <strong>lithiase vésiculaire</strong> (souvent associée).</li><li>Un épaississement de la <strong>paroi de la vésicule</strong>.</li><li>Une <strong>dilatation de la voie biliaire principale</strong> (VBP), bien qu'inconstante.</li><li>Un <strong>calcul de la VBP</strong>, avec une sensibilité de détection de seulement 30 à 50%.</li></ul>"},{"i":"6d6ee847861f","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quelle est l'importance des hémocultures dans le diagnostic de l'angiocholite aiguë et quels germes sont le plus souvent retrouvés ?","a":"<p>Des <strong>hémocultures systématiques</strong> sont réalisées car elles sont souvent positives, révélant la présence de <strong>germes digestifs</strong> (principalement des bacilles Gram négatifs).</p>"},{"i":"ea885f7943a5","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quelle est la définition de l'angiocholite aiguë ?","a":"<p>L'angiocholite aiguë est une <strong>infection aiguë de la voie biliaire principale</strong>, le plus souvent causée par l'enclavement d'un calcul et des germes digestifs (principalement des <strong>bacilles Gram négatifs</strong>).</p>"},{"i":"eaf4d0cc5d74","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quels éléments biologiques sont attendus en cas d'angiocholite aiguë ?","a":"<p>Biologiquement, l'angiocholite aiguë se caractérise par :</p><ul><li>Un <strong>syndrome inflammatoire ou infectieux</strong>.</li><li>Une <strong>cholestase ictérique</strong> (avec bilirubine à prédominance conjuguée).</li><li>Une <strong>cytolyse hépatique</strong>, fréquente en phase aiguë.</li></ul>"},{"i":"f8b9271e39c3","n":277,"o":"277-23","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une lithiase biliaire compliquée : angiocholite aiguë","q":"Quels sont les signes cliniques caractéristiques de l'angiocholite aiguë ?","a":"<p>Les signes cliniques sont regroupés dans la <strong>Triade de Charcot</strong>, apparaissant successivement en 48 heures :</p><ul><li>Une <strong>douleur biliaire</strong>.</li><li>Une <strong>fièvre associée à des frissons</strong> (souvent au premier plan, pouvant être sévère avec bactériémie ou choc).</li><li>Un <strong>ictère</strong> (survient après la douleur ; son absence n'écarte pas le diagnostic).</li></ul>"},{"i":"9ea4b6998b98","n":277,"o":"277-24","u":"Examens complémentaires","t":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","q":"Quel est l'examen paraclinique de première intention en urgence devant une suspicion d'angiocholite aiguë ?","a":"<p>L'examen paraclinique de première intention en urgence devant une angiocholite est l'<strong>échographie abdominale</strong>.</p>"},{"i":"ae734e92dc79","n":277,"o":"277-24","u":"Examens complémentaires","t":"Connaître l’examen paraclinique de première intention (en urgence) devant une angiocholite","q":"Que permet de rechercher l'échographie abdominale en cas d'angiocholite aiguë ?","a":"<p>L'échographie abdominale recherche une <strong>lithiase biliaire</strong> et une éventuelle <strong>dilatation de la voie biliaire principale (VBP)</strong>, bien que cette dernière soit inconstante.</p>"},{"i":"640a66bb5271","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quelle est l'évolution grave de l'angiocholite aigüe caractérisée par une collection purulente dans le foie ?","a":"<p>L'évolution grave de l'angiocholite aigüe caractérisée par une collection purulente intrahépatique est l'<strong>abcès hépatique</strong>.</p>"},{"i":"658f066cb62b","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quelles sont les trois évolutions/complications graves de l'angiocholite aigüe, au-delà du simple tableau d'infection biliaire ?","a":"<p>Les trois évolutions ou complications graves de l'angiocholite aigüe sont :</p><ul><li>L'<strong>abcès hépatique</strong>.</li><li>Le <strong>choc septique</strong> et la <strong>défaillance multiviscérale</strong>.</li><li>L'<strong>angiocholite ictéro-urémigène</strong> (associée à une insuffisance rénale aigüe).</li></ul>"},{"i":"662d00bf3ecb","n":277,"o":"277-25","u":"Identifier une urgence","t":"Connaître les trois évolutions possibles de l’angiocholite","q":"Quel terme désigne spécifiquement l'angiocholite aigüe compliquée d'une insuffisance rénale aigüe ?","a":"<p>L'angiocholite aigüe associée à une insuffisance rénale aigüe est appelée <strong>angiocholite ictéro-urémigène</strong>.</p>"},{"i":"3a41a7c1c735","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Comment doit être réalisée la désobstruction de la VBP en urgence face à une angiocholite avec sepsis sévère ou choc septique ?","a":"<p>La désobstruction de la VBP doit être réalisée en urgence :</p><ul><li>En première intention, par <strong>CPRE</strong> (Cholangiopancréatographie Rétrograde Endoscopique).</li><li>Si la CPRE n'est pas disponible en urgence ou si le patient est instable, un <strong>drainage transcutané des voies biliaires</strong> peut être envisagé.</li></ul>"},{"i":"85cc8d25c396","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Après les mesures de réanimation, quelle est la conduite à tenir pour le traitement d'une angiocholite avec sepsis sévère ou choc septique ?","a":"<p>Après les mesures de réanimation, le traitement repose sur :</p><ul><li>Une <strong>antibiothérapie</strong> adaptée.</li><li>Une <strong>désobstruction de la VBP</strong> (Voie Biliaire Principale) dans les <strong>24 heures</strong>.</li></ul>"},{"i":"fb7618a398be","n":277,"o":"277-26","u":"Prise en charge","t":"Connaître le traitement en cas de sepsis sévère ou choc septique lors d’une angiocholite","q":"Quelle est la priorité de prise en charge en cas d'angiocholite avec sepsis sévère ou choc septique ?","a":"<p>En cas d'angiocholite compliquée de sepsis sévère ou choc septique, la priorité absolue est la mise en œuvre des <strong>mesures de réanimation</strong> avant toute procédure spécifique sur la voie biliaire.</p>"},{"i":"16f119786968","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Quels signes sont absents lors d'une colique hépatique simple et signeraient une complication de la lithiase biliaire ?","a":"<p>Une colique hépatique simple ne comporte <strong>JAMAIS de fièvre ni d'ictère</strong>. Leur présence doit faire évoquer une complication type <strong>cholécystite</strong> ou <strong>angiocholite</strong>.</p>"},{"i":"80d4d93bfbb7","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Comment définir la colique hépatique dans le contexte de la lithiase biliaire ?","a":"<p>La colique hépatique est la manifestation douloureuse d'un <strong>blocage transitoire</strong> du calcul dans les voies biliaires.</p>"},{"i":"8d7506c22338","n":277,"o":"277-9","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur biliaire","q":"Quelles sont les caractéristiques sémiologiques de la douleur biliaire (colique hépatique) ?","a":"<ul><li>Type : <strong>brutale</strong>, <strong>intense</strong>, continue, à type de broiement ou crampe.</li><li>Localisation : <strong>épigastrique</strong> ou <strong>hypochondre droit</strong>.</li><li>Durée : généralement <strong>inférieure à 6 heures</strong>.</li><li>Irradiation : en hémi-ceinture vers l'<strong>épaule</strong> ou l'<strong>omoplate droite</strong>.</li><li>Signes associés : <strong>inhibition de la respiration</strong>, nausées, vomissements.</li><li>Signe spécifique : <strong>Signe de Murphy</strong>.</li></ul>"}]};